mapper.select:
select id,
       dates,
       pkg,
       country,
       `version`,
       register_dates,
       register_day,
       retention_user_num
from dws_daily_package_retention
where dates = #{loginDates}
  and register_dates = #{registerDates}
  and pkg = #{pkg}
  and version = #{version}
  and country = #{country}
